def escape_html(text):
    """
    Escapes special characters for use in HTML content and attributes.
    """
    if not isinstance(text, str):
        return text

    replacements = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }

    result = []
    for char in text:
        if char in replacements:
            result.append(replacements[char])
        else:
            result.append(char)

    return "".join(result)

