def load_config(text):
    """
    Parses a configuration string into a dictionary.
    Supported types: integers, booleans (true/false), JSON-style lists, and strings.
    """
    config = {}
    lines = text.splitlines()

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            continue

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        # Remove trailing comments from value
        if '#' in value:
            value = value.split('#', 1)[0].strip()

        # Handle Booleans
        if value.lower() == 'true':
            config[key] = True
        elif value.lower() == 'false':
            config[key] = False
        else:
            try:
                # Handle Integers
                if value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                    config[key] = int(value)
                # Handle Lists using ast.literal_eval for safe parsing of Python-like lists
                elif value.startswith('[') and value.endswith(']'):
                    result = ast.literal_eval(value)
                    if isinstance(result, list):
                        config[key] = result
                    else:
                        config[key] = value
                else:
                    config[key] = value
            except (ValueError, SyntaxError):
                config[key] = value

    return config

