def can_send(address, allowed_domains):
    """
    Checks if the given address is a single local@domain address 
    whose domain is present in the allowed_domains list.
    """
    if not address or not isinstance(address, str):
        return False

    parts = address.split('@')
    if len(parts) != 2:
        return False

    local_part, domain_part = parts
    if not local_part or not domain_part:
        return False

    normalized_allowed = {d.lower() for d in allowed_domains}

    return domain_part.lower() in normalized_allowed

